/* Visit concept: entry, language, table dialogue, legend and grounded companion. */
const VISIT_PHRASES=[
 {word:'Һаумыһығыҙ!',meaning:'Здравствуйте',say:'хаумы-хыгыз',audio:'https://basic.bashlang.ru/sounds/dictionary/1-1.mp3',hint:'Приветствуем старших и новых знакомых.'},
 {word:'Рәхмәт!',meaning:'Спасибо',say:'рэхмэт',audio:'https://basic.bashlang.ru/sounds/dictionary/1-18.mp3',hint:'Благодарим за угощение и помощь.'},
 {word:'Һау бул!',meaning:'До свидания',say:'хау бул',audio:'https://basic.bashlang.ru/sounds/dictionary/1-9.mp3',hint:'Прощаемся с другом.'},
 {word:'Минең исемем …',meaning:'Меня зовут …',say:'минэнг исемем …',audio:'https://basic.bashlang.ru/sounds/lessons/1-1-3.mp3',hint:'Добавь свой ник. В записи пример: «Меня зовут Айнур».'},
 {word:'Танышыуға шатмын!',meaning:'Рад знакомству',say:'танышыуга шатмын',audio:'https://basic.bashlang.ru/sounds/dictionary/1-27.mp3',hint:'Говорим новому знакомому.'}
];
function visitLoginPage(returning=false){layout(returning?'Продолжим путешествие?':'Как отправимся в путь?',`<div class="game-world"><div class="join-layout"><section class="join-story"><img class="join-marten-helper" src="assets/marten-helper.png" width="240" height="270" alt="Куница — помогающий спутник, показывает на выбор способа игры"><div class="game-panel"><h2>Твой маршрут начинается здесь</h2><p>Можно играть самостоятельно или вместе с группой. Выбери режим и придумай ник. Имя, телефон и почта не нужны.</p></div></section><section class="game-panel"><form id="visitJoin"><fieldset><legend>Твой способ играть</legend><label><input type="radio" name="mode" value="solo" checked> Играть самостоятельно</label><label><input type="radio" name="mode" value="class"> По коду группы</label></fieldset><div id="visitClassField" hidden><label for="visitCode">Код группы</label><input id="visitCode" name="code" maxlength="20" placeholder="Например, ETNO5"></div>${returning?'<label for="visitNick">Ник персонажа</label><input id="visitNick" name="nick" required minlength="2" maxlength="20" autocomplete="nickname">':''}<p id="visitJoinError" role="alert"></p><button class="kid-primary" type="submit">${returning?'Найти персонажа':'Создать персонажа'} ${kidIcon('arrow')}</button></form><p>Персонаж и прогресс сохраняются на этом устройстве. В самостоятельном режиме прогресс не входит в отчёт группы.</p><a class="game-text-link" href="#login${returning?'':'/return'}">${returning?'Создать нового героя':'У меня уже есть персонаж'} →</a></section></div></div>`);document.querySelectorAll('[name="mode"]').forEach(r=>r.onchange=()=>{const isClass=r.value==='class';$('#visitClassField').hidden=!isClass;$('#visitCode').required=isClass});$('#visitJoin').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),mode=f.get('mode'),code=mode==='class'?String(f.get('code')||'').trim().toUpperCase():null,nick=String(f.get('nick')||'').trim();if(mode==='class'&&!db.classes.some(c=>c.code===code)){$('#visitJoinError').textContent='Группа не найдена. Проверь код у организатора.';return}if(returning){const found=db.users.find(v=>v.nick===nick&&(mode==='class'?v.code===code:!v.code));if(!found){$('#visitJoinError').textContent='На этом устройстве такого персонажа нет. Проверь режим и ник.';return}db.current=found.id;pendingJoin=null;creatorState=null;sessionStorage.removeItem('ethnohod-pending-join');save();location.hash=found.character?'map':'character';return}pendingJoin={mode,code,nonce:Date.now()};creatorState=null;setSession('ethnohod-pending-join',pendingJoin);sessionStorage.removeItem('ethnohod-character-draft');location.hash='character'}}
function visitLanguagePage(u,s){const n=Math.min(VISIT_PHRASES.length-1,s.word||0),p=VISIT_PHRASES[n];return `<section class="game-panel visit-language"><h2>Пять фраз для застолья</h2><p>Узнаем слова, которые пригодятся в гостях. Выбери карточку, послушай запись и соедини выражение с переводом.</p><div class="story-language-grid">${VISIT_PHRASES.map((v,i)=>`<button class="btn secondary ${i===n?'active':''}" data-vword="${i}" aria-pressed="${i===n}">${s.words.includes(i)?kidIcon('check'):''}${i+1}. ${v.word}</button>`).join('')}</div><article class="visit-phrase"><h3 lang="ba">${p.word}</h3><p class="visit-pronunciation">Примерно: ${p.say}</p><p>${p.hint}</p><button class="btn secondary" data-phrase-audio="${n}">${kidIcon('compass')} Послушать фразу</button><p class="visit-audio-status" role="status"></p><p class="visit-audio-credit">Учебная запись: <a href="https://basic.bashlang.ru/vocabulary/topic/1/" target="_blank" rel="noopener">Интерактивный башкирский</a>. Русская подсказка передаёт звучание приблизительно.</p></article><h3>Выбери перевод</h3><div class="story-word-answer">${VISIT_PHRASES.map(v=>`<button class="btn secondary" data-vmeaning="${esc(v.meaning)}" ${s.words.includes(n)?'disabled':''}>${v.meaning}</button>`).join('')}</div><p>Выучено ${s.words.length} из 5 фраз. Их можно снова открыть в книге регионов.</p></section>`}
let visitPhraseAudio;
function visitPlayPhrase(n){if(visitPhraseAudio){visitPhraseAudio.pause();visitPhraseAudio=null}const p=VISIT_PHRASES[n];if(!p)return;visitPhraseAudio=new Audio(p.audio);const status=document.querySelector('.visit-audio-status');if(status)status.textContent='Загружаем учебную запись…';visitPhraseAudio.play().then(()=>{if(status)status.textContent='Звучит запись с учебного сайта.'}).catch(()=>{if(status){status.textContent='Запись не загрузилась. Можно открыть оригинал по ссылке ниже.'}})}
const VISIT_TABLE_SCENES=[
 {title:'Знакомство за столом',speaker:'Бабушка',text:'Добро пожаловать! Данияр рассказал, как ты помог с праздником. Как тебя зовут?',prompt:'Представься семье.',right:3},
 {title:'Долгая история народа',speaker:'Бабушка',text:'Башкирский народ формировался веками на Южном Урале и в соседних степях. В его истории встречались местные группы населения и переселявшиеся тюркские племена. Письменные свидетельства, язык и археология помогают учёным изучать этот путь. О деталях происхождения продолжаются научные обсуждения.',prompt:'Данияр знакомит тебя с бабушкой поближе. Ответь: «Рад знакомству».',right:4},
 {title:'В старину и сегодня',speaker:'Данияр',text:'Часть наших предков разводила лошадей и овец, переходила на летние пастбища; уклады жизни различались по местности. Сегодня люди учатся, работают в самых разных профессиях, занимаются наукой, музыкой и спортом. Мы сохраняем традиции, но современная жизнь гораздо шире старинного костюма.',prompt:'Поблагодари Данияра за рассказ.',right:1},
 {title:'Медовый край',speaker:'Бабушка',text:'Попробуй чак-чак, который ты помог приготовить! Мёд напоминает о пчеловодстве. Особая местная традиция — бортничество: пчёл содержат в древесных полостях — бортях. В Шульган-Таше берегут эту традицию и бурзянскую бортевую пчелу. А музыка курая и устные сказания тоже передаются следующим поколениям.',prompt:'Тебя угощают. Как поблагодарить?',right:1}
];
function visitTableArt(){
 return `<figure class="visit-table-scene">
   <img src="assets/family-table.webp" width="1200" height="675" alt="Данияр и бабушка встречают гостя за накрытым столом">
   <figcaption>${[['soup','Тукмас'],['beshbarmak','Бешбармак'],['chak','Чак-чак']].map(([art,name])=>
     `<span><img src="assets/kitchen/${art}.png" width="192" height="160" alt=""><b>${name}</b></span>`).join('')}</figcaption>
 </figure>`;
}
function visitDinnerPage(u,s){const n=Math.min(3,s.dinnerIndex||0),scene=VISIT_TABLE_SCENES[n],done=(s.dinnerDone||[]).includes(n),options=[scene.right,(scene.right+1)%5,(scene.right+3)%5];return `${visitTableArt()}<section class="story-dialogue game-panel visit-dinner"><h2>${scene.title}</h2><p><strong>${scene.speaker}:</strong> ${scene.text}</p><p data-marten-task>${scene.prompt}</p><div class="visit-dialogue-answers">${options.map(i=>`<button class="btn secondary" data-dinner-answer="${i}" ${done?'disabled':''}><span lang="ba">${VISIT_PHRASES[i].word}${i===3?' '+esc(u.nick):''}</span></button>`).join('')}</div><p class="visit-dinner-status" id="dinner-status" role="status" tabindex="-1">${done?'Фраза подходит к ситуации.':esc(s.feedback||'')}</p>${done?`${n<3?'<button class="kid-primary" data-dinner-next>Продолжить разговор →</button>':'<p>Семья рада знакомству. Все четыре разговора сохранены в книге.</p>'}`:''}<p>Разговор ${n+1} из 4</p></section>`}
const VISIT_EPIC_FRAMES=[
 ['Путь начинается','В сказании богатырь Урал ищет живой родник, чтобы защитить людей от смерти. Его путь начинается среди гор и степей.'],
 ['Через леса и реки','В дороге Урал встречает испытания. Сила нужна ему, чтобы помогать другим и бороться со злом.'],
 ['Выбор героя','На пути героя — дивы и другие фантастические противники. Эпос показывает разные поступки и их последствия.'],
 ['Живой родник','Урал находит источник живой воды. Но важнее самой находки — решить, ради чего ею воспользоваться.'],
 ['Подарок живому миру','Герой выбирает жизнь природы вместо собственного бессмертия. В пересказе вода становится даром земле и будущим поколениям.'],
 ['Память остаётся','Эпос связывает образ героя с Уральскими горами. Сказители — сэсэны — передавали его устно; в 1910 году сказание записал Мухаметша Бурангулов. Это фольклор, а не историческая хроника.']
];
function visitLegendPage(u,s){if(!s.legendChoice)return `<section class="game-panel visit-legend-invite">${storyHuman(true)}<div><h2>Рассказать об Урал-батыре?</h2><p>Шесть иллюстрированных страниц о выборе героя, людях и природе. Можно остаться на 2–3 минуты или сразу перейти к прощанию.</p><button class="kid-primary" data-legend-choice="yes">Да, хочу услышать</button><button class="btn secondary" data-legend-choice="no">В другой раз</button></div></section>`;if(s.legendChoice==='no')return '<section class="game-panel"><h2>Легенда подождёт</h2><button type="button" class="btn secondary" data-legend-choice="yes">Вернуться к пересказу</button></section>';const n=Math.min(5,s.legendFrame||0),f=VISIT_EPIC_FRAMES[n];return `<section class="game-panel visit-legend"><div class="visit-legend-picture" style="--epic-x:${n%2?100:0}%;--epic-y:${Math.floor(n/2)*50}%" role="img" aria-label="${esc(f[0])}"></div><h2>${f[0]}</h2><p>${f[1]}</p><p>Страница ${n+1} из 6</p><div class="game-actions">${n?'<button class="btn secondary" data-legend-back>← Назад</button>':''}${n<5?'<button class="kid-primary" data-legend-next>Листать дальше →</button>':'<button class="kid-primary" data-legend-done>Сохранить легенду в книгу</button>'}</div></section>`}
function wireVisitNarrative(u,s,redraw){document.querySelectorAll('[data-vword]').forEach(b=>b.onclick=()=>{s.word=+b.dataset.vword;redraw('[data-vword="'+s.word+'"]')});document.querySelectorAll('[data-vmeaning]').forEach(b=>b.onclick=()=>{const n=s.word||0;if(b.dataset.vmeaning===VISIT_PHRASES[n].meaning){if(!s.words.includes(n))s.words.push(n);s.feedback='Верно! '+VISIT_PHRASES[n].word+' — '+VISIT_PHRASES[n].meaning+'.'}else{visitRecord(u,'error',{topic:'language'});s.feedback='Данияр подсказывает: '+VISIT_PHRASES[n].hint}redraw('#storyFeedback')});document.querySelectorAll('[data-phrase-audio]').forEach(b=>b.onclick=()=>visitPlayPhrase(+b.dataset.phraseAudio));document.querySelectorAll('[data-dinner-answer]').forEach(b=>b.onclick=()=>{const n=s.dinnerIndex||0;if(+b.dataset.dinnerAnswer===VISIT_TABLE_SCENES[n].right){s.dinnerDone=s.dinnerDone||[];if(!s.dinnerDone.includes(n))s.dinnerDone.push(n);s.grandma=s.dinnerDone.map(i=>['origins','today','honey','kurai'][i]);s.feedback=''}else{visitRecord(u,'error',{topic:'dialogue'});s.feedback='Попробуй ещё. Ищи фразу со значением «'+VISIT_PHRASES[VISIT_TABLE_SCENES[n].right].meaning+'».'}redraw('#dinner-status')});document.querySelector('[data-dinner-next]')?.addEventListener('click',()=>{s.dinnerIndex=Math.min(3,(s.dinnerIndex||0)+1);s.feedback='';redraw()});document.querySelectorAll('[data-legend-choice]').forEach(b=>b.onclick=()=>{s.legendChoice=b.dataset.legendChoice;s.feedback='';redraw()});document.querySelector('[data-legend-next]')?.addEventListener('click',()=>{s.legendFrame=Math.min(5,(s.legendFrame||0)+1);redraw()});document.querySelector('[data-legend-back]')?.addEventListener('click',()=>{s.legendFrame=Math.max(0,(s.legendFrame||0)-1);redraw()});document.querySelector('[data-legend-done]')?.addEventListener('click',()=>{s.legendRead=true;s.epic='read';visitRecord(u,'legendRead');s.feedback='Легенда сохранена в твоей книге.';redraw('#storyFeedback')})}
const VISIT_KNOWLEDGE=[
 {topic:'cooking',keys:['еда','готов','чак','рецепт','мед','мёд','блюд','тукмас','бешбармак'],title:'Угощение семьи',text:'В нашей главе готовим чак-чак, бешбармак и тукмас. У этих блюд много семейных вариантов; они встречаются у разных народов. Чак-чак соединяет кусочки теста с медовой заливкой, тукмас — домашняя лапша и суп с ней.',url:'https://www.culture.ru/live/movies/71732/master-klass-domashnyaya-lapsha-dlya-soldat'},
 {topic:'language',keys:['язык','слов','фраз','спасибо','привет','башкирск','рәхмәт'],title:'Первые фразы',text:'Һаумыһығыҙ! — здравствуйте. Рәхмәт! — спасибо. Һау бул! — до свидания. Минең исемем … — меня зовут … . Танышыуға шатмын! — рад знакомству. В книге можно открыть учебные записи и переводы.',url:'https://basic.bashlang.ru/vocabulary/topic/1/'},
 {topic:'pattern',keys:['узор','наряд','костюм','блок','орнамент','пазл'],title:'Как собирать узоры',text:'Выбери фигуру и повтори образец на поле 8×8. Собранные мотивы сохраняются в Книге открытий. Игровые мотивы — условные эскизы; мы не приписываем им непроверенные традиционные значения.',url:'https://www.culture.ru/'},
 {topic:'legend',keys:['урал','легенд','батыр','эпос','сэсэн'],title:'История Урал-батыра',text:'Урал-батыр — башкирский эпос, который передавали сказители-сэсэны. Его герой выбирает благо людей и природы. Это художественное сказание. В игре есть необязательная иллюстрированная легенда.',url:'https://www.culture.ru/live/broadcast/161585/narodnyi-epos-ural-batyr'},
 {topic:'dialogue',keys:['народ','башкир','истор','происх','живут','уфа','регион','сабантуй'],title:'В гостях в Башкортостане',text:'Башкортостан находится на Южном Урале и в Предуралье, столица — Уфа. История башкирского народа складывалась веками с участием разных групп населения. Сегодня люди выбирают самые разные занятия, а семейные традиции соседствуют с современной жизнью.',url:'https://assembly.kz/ru/ethnos/ru/bashkiry/'}
];
function visitGuidePage(){return `<div class="game-world"><div class="game-guide-grid"><section class="game-panel game-guide-card">${visitCompanionMarkup()}<h2>Я рядом, если нужна подсказка</h2><p>Можно спросить про путешествие или поговорить на другую тему.</p>${martenButton('chat')}</section><section class="game-panel"><form id="visitAsk"><label for="visitQuestion">Поиск по материалам игры</label><input id="visitQuestion" maxlength="250" required placeholder="Как собрать узоры?"><button class="kid-primary">Найти в материалах</button></form><div class="game-actions">${['Как готовить чак-чак?','Как сказать спасибо?','Как собрать узоры?','Кто такой Урал-батыр?'].map(t=>`<button class="btn secondary" data-ask="${t}">${t}</button>`).join('')}</div><div id="visitReply" role="status" aria-live="polite"><p>Выбери тему или введи вопрос, чтобы найти справку и источник.</p></div><a class="game-text-link" href="#map">Вернуться к карте →</a></section></div></div>`}
function wireVisitGuide(){const ask=q=>{const words=q.toLowerCase(),rank=VISIT_KNOWLEDGE.map(k=>({k,score:k.keys.filter(w=>words.includes(w)).length})).sort((a,b)=>b.score-a.score),hit=rank[0];if(hit.score){visitRecord(user(),'question',{topic:hit.k.topic});$('#visitReply').innerHTML=`<h3>${hit.k.title}</h3><p>${hit.k.text}</p><a href="${hit.k.url}" target="_blank" rel="noopener">Читать источник ↗</a>`}else{$('#visitReply').innerHTML='<h3>Этого пока нет в моей книге</h3><p>Я могу подсказать про кухню, узоры, язык, историю и Урал-батыра. Попробуй спросить об одной из этих тем.</p>'}};$('#visitAsk').onsubmit=e=>{e.preventDefault();ask($('#visitQuestion').value)};document.querySelectorAll('[data-ask]').forEach(b=>b.onclick=()=>{ $('#visitQuestion').value=b.dataset.ask;ask(b.dataset.ask)})}
